param([Parameter(Mandatory)][string]$OutputPath,[string]$PlanPath=(Join-Path $PSScriptRoot 'decimal-create-checked-integer-carriers-plan-v1.json'))
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$coreHash=(Get-FileHash -LiteralPath ([object].Assembly.Location) -Algorithm SHA256).Hash.ToLowerInvariant();if([Environment]::Version.ToString() -ne '10.0.12' -or $coreHash -ne '1125acc8106c43fc8bad2d203c4c4485df6182d292846c2fff415c1040c54678'){throw 'Pinned CoreLib required'}
[Globalization.CultureInfo]::CurrentCulture=[Globalization.CultureInfo]::InvariantCulture;[Globalization.CultureInfo]::CurrentUICulture=[Globalization.CultureInfo]::InvariantCulture
$plan=Get-Content -LiteralPath $PlanPath -Raw|ConvertFrom-Json
function Failure($Record){$e=$Record.Exception;while($e -is [Reflection.TargetInvocationException] -or $e -is [Management.Automation.MethodInvocationException]){$e=$e.InnerException};return [ordered]@{ok=$false;exception=$e.GetType().FullName;messageUnits=[int[]][char[]]$e.Message;hResult=$e.HResult;paramName=$(if($e -is [ArgumentException]){$e.ParamName}else{$null})}}
$definition=@([decimal].GetMethods([Reflection.BindingFlags]'Public,Static')|Where-Object {$_.Name -eq 'CreateChecked' -and $_.IsGenericMethodDefinition});if($definition.Count -ne 1){throw 'One generic CreateChecked definition required'};$rows=[Collections.Generic.List[object]]::new()
foreach($property in $plan.values.PSObject.Properties){$typeName=$property.Name;$native=if($typeName -eq 'System.Numerics.BigInteger'){[Numerics.BigInteger]}else{[type]::GetType($typeName,$true)};$closed=$definition[0].MakeGenericMethod([type[]]@($native));$parse=$native.GetMethod('Parse',[type[]]@([string],[IFormatProvider]));for($index=0;$index -lt $property.Value.Count;$index++){$text=$property.Value[$index];if($typeName -eq 'System.Char'){$value=[char][int]$text}elseif($typeName -eq 'System.IntPtr'){$value=[IntPtr]::new([long]$text)}elseif($typeName -eq 'System.UIntPtr'){$value=[UIntPtr]::new([ulong]$text)}elseif($null -ne $parse){$value=$parse.Invoke($null,[object[]]@($text,[Globalization.CultureInfo]::InvariantCulture))}else{$value=[Convert]::ChangeType($text,$native,[Globalization.CultureInfo]::InvariantCulture)};if($value.GetType() -ne $native){throw 'Input type mismatch'};try{$actual=[decimal]$closed.Invoke($null,[object[]]@($value));$result=[ordered]@{ok=$true;bits=[decimal]::GetBits($actual)}}catch{$result=Failure $_};$rows.Add([ordered]@{type=$typeName;index=$index;input=$text;result=$result})}}
$closed=$definition[0].MakeGenericMethod([type[]]@([decimal]));for($index=0;$index -lt $plan.decimalBits.Count;$index++){$value=[decimal]::new([int[]]$plan.decimalBits[$index]);try{$actual=[decimal]$closed.Invoke($null,[object[]]@($value));$result=[ordered]@{ok=$true;bits=[decimal]::GetBits($actual)}}catch{$result=Failure $_};$rows.Add([ordered]@{type='System.Decimal';index=$index;inputBits=$plan.decimalBits[$index];result=$result})}
$record=[ordered]@{schemaVersion=1;runtimeVersion=[Environment]::Version.ToString();coreLibSha256=$coreHash;oracleSha256=(Get-FileHash -LiteralPath $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();planSha256=(Get-FileHash -LiteralPath $PlanPath -Algorithm SHA256).Hash.ToLowerInvariant();culture='Invariant';rows=$rows.ToArray();qualification=$plan.qualification};[IO.File]::WriteAllText($OutputPath,($record|ConvertTo-Json -Depth 18 -Compress)+"`n",[Text.UTF8Encoding]::new($false));Write-Output "PASS Decimal CreateChecked integer/Decimal: $($rows.Count) native calls"
